52	/// Package identity across ecosystems.
53	#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
54	#[serde(try_from = "String")]
55	pub enum PackageId {
56	    Bare(String),
57	    Prefixed { ecosystem: Ecosystem, name: String },
58	}
59	
60	string_json_schema!(PackageId);
61	
62	impl PackageId {
63	    /// Parses package identity string.
64	    ///
65	    /// # Errors
66	    ///
67	    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
68	    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
69	        if s.is_empty() {
70	            return Err(PackageIdParseError::Empty);
71	        }
72	        if s.starts_with('/') {
73	            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
74	        }
75	        if s.starts_with('-') {
76	            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
77	        }
78	        if s.contains("..") {
79	            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
80	        }
81	
82	        if let Some((prefix, remainder)) = s.split_once(':')
83	            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
84	        {
85	            Self::validate_prefixed_remainder(s, prefix, remainder)?;
86	            return Ok(PackageId::Prefixed {
87	                ecosystem,
88	                name: remainder.to_string(),
89	            });
90	        }
91	
92	        if let Some((prefix, remainder)) = s.split_once('/')
93	            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
94	        {
95	            Self::validate_prefixed_remainder(s, prefix, remainder)?;
96	            return Ok(PackageId::Prefixed {
97	                ecosystem,
98	                name: remainder.to_string(),
99	            });
100	        }
101	
102	        Ok(PackageId::Bare(s.to_string()))
103	    }
104	
105	    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
106	    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
107	    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
108	        if remainder.is_empty() {
109	            return Err(PackageIdParseError::EmptyNameAfterPrefix {
110	                raw: raw.to_string(),
111	                prefix: prefix.to_string(),
112	            });
113	        }
114	        if remainder.starts_with('-') {
115	            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
116	        }
117	        if remainder.contains("..") {
118	            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
119	        }
120	        Ok(())
121	    }
122	
123	    /// The slash form of a colon-qualified reference (`cargo:foo` becomes `cargo/foo`), or `None` when `s` is not one.
124	    pub fn colon_form_canonical(s: &str) -> Option<String> {
125	        let (prefix, remainder) = s.split_once(':')?;
126	        (Ecosystem::from_prefix(prefix).is_some() && !remainder.is_empty()).then(|| format!("{prefix}/{remainder}"))
127	    }
128	
129	    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
130	    pub fn display_name(&self) -> String {
131	        match self {
132	            PackageId::Bare(name) => name.clone(),
133	            PackageId::Prefixed { ecosystem, name } => {
134	                format!("{}/{}", ecosystem.prefix(), name)
135	            }
136	        }
137	    }
138	
139	    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
140	    pub fn ecosystem(&self) -> Option<Ecosystem> {
141	        match self {
142	            PackageId::Bare(_) => None,
143	            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
144	        }
145	    }
146	
147	    /// Returns the package name without any ecosystem prefix.
148	    pub fn name(&self) -> &str {
149	        match self {
150	            PackageId::Bare(name) => name,
151	            PackageId::Prefixed { name, .. } => name,
152	        }
153	    }
154	
155	    /// Weak "could be the same package" check, not strict equality.
156	    ///
157	    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
158	    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
159	    /// equality always matches.
160	    ///
161	    /// **Caller contract**: a bare lookup can match packages in two or more ecosystems, so a caller must
162	    /// collect all matches and error on 2+, never take the first silently. Resolving a changeset or config
163	    /// selector goes through the workspace identity index instead, which also knows each manifest's own name.
164	    pub fn matches(&self, other: &Self) -> bool {
165	        if self == other {
166	            return true;
167	        }
168	        if self.name() == other.name() {
169	            match (self.ecosystem(), other.ecosystem()) {
170	                (None, _) | (_, None) => true,
171	                (Some(e1), Some(e2)) => e1 == e2,
172	            }
173	        } else {
174	            false
175	        }
176	    }
177	}
