240	/// Defines the `as_str`/`Display` pair shared by every single-field `String`
241	/// newtype in this crate, regardless of how the rest of the type (fields,
242	/// derives, serde impls) is shaped.
243	macro_rules! string_newtype_display {
244	    ($name:ident) => {
245	        impl $name {
246	            #[doc = concat!("Returns the ", stringify!($name), " as a string slice.")]
247	            pub fn as_str(&self) -> &str {
248	                &self.0
249	            }
250	        }
251	
252	        impl ::std::fmt::Display for $name {
253	            fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
254	                f.write_str(&self.0)
255	            }
256	        }
257	    };
258	}
