262	/// Defines a plain single-field `String` newtype: the common derive list,
263	/// `#[schemars(with = "String")]`, transparent (unvalidated) serde, `as_str`,
264	/// and `Display`. For newtypes that validate on construction/deserialize
265	/// (e.g. [`TagName`](crate::tag::TagName), [`CommitSha`]), use
266	/// [`string_newtype_display!`] instead and hand-write the rest.
267	macro_rules! string_newtype {
268	    ($(#[$doc:meta])* $name:ident) => {
269	        $(#[$doc])*
270	        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
271	        #[schemars(with = "String")]
272	        #[serde(transparent)]
273	        pub struct $name(pub String);
274	
275	        string_newtype_display!($name);
276	    };
277	}
