334	impl CommitSha {
335	    /// Parses a 40-character hexadecimal Git commit SHA, trimming surrounding whitespace.
336	    ///
337	    /// # Errors
338	    ///
339	    /// Returns `Err(ModelError::InvalidCommitSha)` if the trimmed input is not exactly 40 ASCII hex digits.
340	    pub fn parse(s: &str) -> Result<Self, ModelError> {
341	        let trimmed = s.trim();
342	        if trimmed.len() != 40 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
343	            return Err(ModelError::InvalidCommitSha {
344	                raw: s.to_string(),
345	                reason: "must be exactly 40 hexadecimal characters".to_string(),
346	            });
347	        }
348	        Ok(CommitSha(trimmed.to_lowercase()))
349	    }
