use std::cmp::Ordering;
use std::fmt;
use std::path::{Path, PathBuf};
use std::str::FromStr;

use schemars::JsonSchema;
use serde::{Deserialize, Serialize, Serializer};

use crate::{Ecosystem, ModelError};

// String wire leaves retain their domain names when used as schema definitions.
macro_rules! string_json_schema {
    ($name:ident) => {
        impl ::schemars::JsonSchema for $name {
            fn schema_name() -> ::std::borrow::Cow<'static, str> {
                ::std::borrow::Cow::Borrowed(stringify!($name))
            }

            fn schema_id() -> ::std::borrow::Cow<'static, str> {
                ::std::borrow::Cow::Borrowed(concat!(module_path!(), "::", stringify!($name)))
            }

            fn json_schema(generator: &mut ::schemars::SchemaGenerator) -> ::schemars::Schema {
                <String as ::schemars::JsonSchema>::json_schema(generator)
            }
        }
    };
}

pub(crate) use string_json_schema;

/// A package's stable internal key: its workspace-relative directory. Promotion to `eco/name` never changes it.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct PackageKey(PathBuf);

impl PackageKey {
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        PackageKey(dir.into())
    }

    pub fn as_path(&self) -> &Path {
        &self.0
    }
}

impl fmt::Display for PackageKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0.display())
    }
}

/// Package identity across ecosystems.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
#[serde(try_from = "String")]
pub enum PackageId {
    Bare(String),
    Prefixed { ecosystem: Ecosystem, name: String },
}

string_json_schema!(PackageId);

impl PackageId {
    /// Parses package identity string.
    ///
    /// # Errors
    ///
    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
        if s.is_empty() {
            return Err(PackageIdParseError::Empty);
        }
        if s.starts_with('/') {
            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
        }
        if s.starts_with('-') {
            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
        }
        if s.contains("..") {
            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
        }

        if let Some((prefix, remainder)) = s.split_once(':')
            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
        {
            Self::validate_prefixed_remainder(s, prefix, remainder)?;
            return Ok(PackageId::Prefixed {
                ecosystem,
                name: remainder.to_string(),
            });
        }

        if let Some((prefix, remainder)) = s.split_once('/')
            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
        {
            Self::validate_prefixed_remainder(s, prefix, remainder)?;
            return Ok(PackageId::Prefixed {
                ecosystem,
                name: remainder.to_string(),
            });
        }

        Ok(PackageId::Bare(s.to_string()))
    }

    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
        if remainder.is_empty() {
            return Err(PackageIdParseError::EmptyNameAfterPrefix {
                raw: raw.to_string(),
                prefix: prefix.to_string(),
            });
        }
        if remainder.starts_with('-') {
            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
        }
        if remainder.contains("..") {
            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
        }
        Ok(())
    }

    /// The slash form of a colon-qualified reference (`cargo:foo` becomes `cargo/foo`), or `None` when `s` is not one.
    pub fn colon_form_canonical(s: &str) -> Option<String> {
        let (prefix, remainder) = s.split_once(':')?;
        (Ecosystem::from_prefix(prefix).is_some() && !remainder.is_empty()).then(|| format!("{prefix}/{remainder}"))
    }

    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
    pub fn display_name(&self) -> String {
        match self {
            PackageId::Bare(name) => name.clone(),
            PackageId::Prefixed { ecosystem, name } => {
                format!("{}/{}", ecosystem.prefix(), name)
            }
        }
    }

    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
    pub fn ecosystem(&self) -> Option<Ecosystem> {
        match self {
            PackageId::Bare(_) => None,
            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
        }
    }

    /// Returns the package name without any ecosystem prefix.
    pub fn name(&self) -> &str {
        match self {
            PackageId::Bare(name) => name,
            PackageId::Prefixed { name, .. } => name,
        }
    }

    /// Weak "could be the same package" check, not strict equality.
    ///
    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
    /// equality always matches.
    ///
    /// **Caller contract**: a bare lookup can match packages in two or more ecosystems, so a caller must
    /// collect all matches and error on 2+, never take the first silently. Resolving a changeset or config
    /// selector goes through the workspace identity index instead, which also knows each manifest's own name.
    pub fn matches(&self, other: &Self) -> bool {
        if self == other {
            return true;
        }
        if self.name() == other.name() {
            match (self.ecosystem(), other.ecosystem()) {
                (None, _) | (_, None) => true,
                (Some(e1), Some(e2)) => e1 == e2,
            }
        } else {
            false
        }
    }
}

impl fmt::Display for PackageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.display_name())
    }
}

impl FromStr for PackageId {
    type Err = PackageIdParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        PackageId::parse(s)
    }
}

impl PartialOrd for PackageId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for PackageId {
    fn cmp(&self, other: &Self) -> Ordering {
        let key_self = (self.ecosystem(), self.name());
        let key_other = (other.ecosystem(), other.name());
        key_self.cmp(&key_other)
    }
}

impl Serialize for PackageId {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.display_name())
    }
}

impl TryFrom<String> for PackageId {
    type Error = PackageIdParseError;

    fn try_from(raw: String) -> Result<Self, Self::Error> {
        Self::parse(&raw)
    }
}

/// Errors produced by [`PackageId::parse`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum PackageIdParseError {
    #[error("package identity is empty")]
    Empty,
    #[error("package identity `{raw}` has ecosystem prefix `{prefix}` but no name after it")]
    EmptyNameAfterPrefix { raw: String, prefix: String },
    #[error("`{raw}` starts with `/`")]
    LeadingSlash { raw: String },
    #[error("package identity `{raw}` contains path traversal `..`")]
    PathTraversal { raw: String },
    #[error("package identity `{raw}` starts with `-`, which could be misread as a command-line flag")]
    LeadingHyphen { raw: String },
}

/// Defines the `as_str`/`Display` pair shared by every single-field `String`
/// newtype in this crate, regardless of how the rest of the type (fields,
/// derives, serde impls) is shaped.
macro_rules! string_newtype_display {
    ($name:ident) => {
        impl $name {
            #[doc = concat!("Returns the ", stringify!($name), " as a string slice.")]
            pub fn as_str(&self) -> &str {
                &self.0
            }
        }

        impl ::std::fmt::Display for $name {
            fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
                f.write_str(&self.0)
            }
        }
    };
}

pub(crate) use string_newtype_display;

/// Defines a plain single-field `String` newtype: the common derive list,
/// `#[schemars(with = "String")]`, transparent (unvalidated) serde, `as_str`,
/// and `Display`. For newtypes that validate on construction/deserialize
/// (e.g. [`TagName`](crate::tag::TagName), [`CommitSha`]), use
/// [`string_newtype_display!`] instead and hand-write the rest.
macro_rules! string_newtype {
    ($(#[$doc:meta])* $name:ident) => {
        $(#[$doc])*
        #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
        #[schemars(with = "String")]
        #[serde(transparent)]
        pub struct $name(pub String);

        string_newtype_display!($name);
    };
}

