1	use std::cmp::Ordering;
2	use std::fmt;
3	use std::path::{Path, PathBuf};
4	use std::str::FromStr;
5	
6	use schemars::JsonSchema;
7	use serde::{Deserialize, Serialize, Serializer};
8	
9	use crate::{Ecosystem, ModelError};
10	
11	// String wire leaves retain their domain names when used as schema definitions.
12	macro_rules! string_json_schema {
13	    ($name:ident) => {
14	        impl ::schemars::JsonSchema for $name {
15	            fn schema_name() -> ::std::borrow::Cow<'static, str> {
16	                ::std::borrow::Cow::Borrowed(stringify!($name))
17	            }
18	
19	            fn schema_id() -> ::std::borrow::Cow<'static, str> {
20	                ::std::borrow::Cow::Borrowed(concat!(module_path!(), "::", stringify!($name)))
21	            }
22	
23	            fn json_schema(generator: &mut ::schemars::SchemaGenerator) -> ::schemars::Schema {
24	                <String as ::schemars::JsonSchema>::json_schema(generator)
25	            }
26	        }
27	    };
28	}
29	
30	pub(crate) use string_json_schema;
31	
32	/// A package's stable internal key: its workspace-relative directory. Promotion to `eco/name` never changes it.
33	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
34	pub struct PackageKey(PathBuf);
35	
36	impl PackageKey {
37	    pub fn new(dir: impl Into<PathBuf>) -> Self {
38	        PackageKey(dir.into())
39	    }
40	
41	    pub fn as_path(&self) -> &Path {
42	        &self.0
43	    }
44	}
45	
46	impl fmt::Display for PackageKey {
47	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
48	        write!(f, "{}", self.0.display())
49	    }
50	}
51	
52	/// Package identity across ecosystems.
53	#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
54	#[serde(try_from = "String")]
55	pub enum PackageId {
56	    Bare(String),
57	    Prefixed { ecosystem: Ecosystem, name: String },
58	}
59	
60	string_json_schema!(PackageId);
61	
62	impl PackageId {
63	    /// Parses package identity string.
64	    ///
65	    /// # Errors
66	    ///
67	    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
68	    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
69	        if s.is_empty() {
70	            return Err(PackageIdParseError::Empty);
71	        }
72	        if s.starts_with('/') {
73	            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
74	        }
75	        if s.starts_with('-') {
76	            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
77	        }
78	        if s.contains("..") {
79	            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
80	        }
81	
82	        if let Some((prefix, remainder)) = s.split_once(':')
83	            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
84	        {
85	            Self::validate_prefixed_remainder(s, prefix, remainder)?;
86	            return Ok(PackageId::Prefixed {
87	                ecosystem,
88	                name: remainder.to_string(),
89	            });
90	        }
91	
92	        if let Some((prefix, remainder)) = s.split_once('/')
93	            && let Some(ecosystem) = Ecosystem::from_prefix(prefix)
94	        {
95	            Self::validate_prefixed_remainder(s, prefix, remainder)?;
96	            return Ok(PackageId::Prefixed {
97	                ecosystem,
98	                name: remainder.to_string(),
99	            });
100	        }
101	
102	        Ok(PackageId::Bare(s.to_string()))
103	    }
104	
105	    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
106	    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
107	    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
108	        if remainder.is_empty() {
109	            return Err(PackageIdParseError::EmptyNameAfterPrefix {
110	                raw: raw.to_string(),
111	                prefix: prefix.to_string(),
112	            });
113	        }
114	        if remainder.starts_with('-') {
115	            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
116	        }
117	        if remainder.contains("..") {
118	            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
119	        }
120	        Ok(())
121	    }
