123	    /// The slash form of a colon-qualified reference (`cargo:foo` becomes `cargo/foo`), or `None` when `s` is not one.
124	    pub fn colon_form_canonical(s: &str) -> Option<String> {
125	        let (prefix, remainder) = s.split_once(':')?;
126	        (Ecosystem::from_prefix(prefix).is_some() && !remainder.is_empty()).then(|| format!("{prefix}/{remainder}"))
127	    }
