129	    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
130	    pub fn display_name(&self) -> String {
131	        match self {
132	            PackageId::Bare(name) => name.clone(),
133	            PackageId::Prefixed { ecosystem, name } => {
134	                format!("{}/{}", ecosystem.prefix(), name)
135	            }
136	        }
137	    }
138	
139	    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
140	    pub fn ecosystem(&self) -> Option<Ecosystem> {
141	        match self {
142	            PackageId::Bare(_) => None,
143	            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
144	        }
145	    }
