247	            pub fn as_str(&self) -> &str {
248	                &self.0
249	            }
250	        }
251	
252	        impl ::std::fmt::Display for $name {
253	            fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
