352	    pub fn as_str(&self) -> &str {
353	        &self.0
354	    }
355	
356	    /// Returns the first 7 characters of the SHA, matching git's short-ref convention.
357	    pub fn short(&self) -> &str {
358	        &self.0[..7]
359	    }
360	}
