379	#[cfg(test)]
380	pub(crate) fn assert_string_wire_schema<T>(value: &T, name: &str, wire: &str)
381	where
382	    T: JsonSchema + Serialize + serde::de::DeserializeOwned,
383	{
384	    assert_eq!(
385	        serde_json::to_string(value).unwrap(),
386	        serde_json::to_string(wire).unwrap()
387	    );
388	
389	    let root = serde_json::to_value(schemars::schema_for!(T)).unwrap();
390	    assert_eq!(root["title"], name);
391	    assert_eq!(root["type"], "string");
392	    assert_eq!(root["$schema"], "https://json-schema.org/draft/2020-12/schema");
393	
394	    let mut generator = schemars::SchemaGenerator::default();
395	    let reference = serde_json::to_value(generator.subschema_for::<T>()).unwrap();
396	    assert_eq!(reference["$ref"], format!("#/$defs/{name}"));
397	    assert_eq!(
398	        generator.definitions()[name],
399	        <String as JsonSchema>::json_schema(&mut schemars::SchemaGenerator::default())
400	    );
401	
402	    for invalid in [
403	        serde_json::json!({ "raw": wire }),
404	        serde_json::json!([wire]),
405	        serde_json::json!(1),
406	        serde_json::json!(true),
407	        serde_json::Value::Null,
408	    ] {
409	        assert!(serde_json::from_value::<T>(invalid).is_err());
410	    }
411	}
