23	impl Package {
24	    /// The directory of the first canonical manifest; `None` only for a package without one.
25	    pub fn key(&self) -> Option<PackageKey> {
26	        let manifest = self.canonical_manifests().next()?;
27	        Some(PackageKey::new(manifest.path.parent().unwrap_or(Path::new(""))))
28	    }
