30	    /// The id reports and diagnostics print: `ecosystem/name` for the package's primary ecosystem (the same one
31	    /// identity assignment promotes to), whether or not the package was ever promoted. A package with no canonical
32	    /// manifest keeps its id.
33	    pub fn canonical_id(&self) -> PackageId {
34	        self.canonical_manifests()
35	            .map(|manifest| manifest.ecosystem())
36	            .min_by_key(|ecosystem| ecosystem.primary_priority())
37	            .map_or_else(
38	                || self.id.clone(),
39	                |ecosystem| PackageId::Prefixed {
40	                    ecosystem,
41	                    name: self.id.name().to_string(),
42	                },
43	            )
44	    }
