46	    pub fn canonical_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
47	        self.manifests.iter().filter(|m| m.role == ManifestRole::Canonical)
48	    }
49	
50	    pub fn platform_manifests(&self) -> impl Iterator<Item = &ManifestDecl> {
51	        self.manifests
52	            .iter()
53	            .filter(|m| matches!(m.role, ManifestRole::Platform { .. }))
54	    }
55	
56	    pub fn lockfiles(&self) -> impl Iterator<Item = &ManifestDecl> {
57	        self.manifests.iter().filter(|m| m.role == ManifestRole::Lockfile)
58	    }
59	
60	    pub fn version_grammar(&self) -> Result<VersionGrammar, ModelError> {
61	        let grammars: Vec<_> = self
62	            .canonical_manifests()
63	            .map(|m| m.format.ecosystem().version_grammar())
64	            .collect();
65	
66	        if grammars.is_empty() {
67	            return Err(ModelError::no_canonical_manifest(&self.id));
68	        }
69	
70	        let first = grammars[0];
71	        if grammars.iter().any(|&g| g != first) {
72	            let mut unique = grammars;
73	            unique.sort();
74	            unique.dedup();
75	            return Err(ModelError::mixed_version_grammars(&self.id, unique));
76	        }
77	
78	        Ok(first)
79	    }
