222	    pub fn from_path(p: &std::path::Path) -> Result<Self, ModelError> {
223	        let name = p
224	            .file_name()
225	            .and_then(|n| n.to_str())
226	            .ok_or_else(|| ModelError::UnknownManifestFormat { path: p.to_path_buf() })?;
227	        match name {
228	            "Cargo.toml" => Ok(ManifestFormat::CargoToml),
229	            "package.json" => Ok(ManifestFormat::PackageJson),
230	            "pyproject.toml" => Ok(ManifestFormat::PyprojectToml),
