186	    /// Extracts every `code(E<digits>)` occurrence from `text`, in order of appearance. Deliberately
187	    /// a hand-rolled scan rather than a `regex` dependency — the pattern is fixed-shape and simple
188	    /// enough that adding a whole crate dependency for it isn't warranted.
189	    fn extract_diagnostic_codes(text: &str) -> Vec<String> {
190	        let mut codes = Vec::new();
191	        let mut rest = text;
192	        while let Some(start) = rest.find("code(E") {
193	            let after_marker = &rest[start + "code(".len()..];
194	            let digit_end = after_marker
195	                .find(|c: char| !c.is_ascii_digit() && c != 'E')
196	                .unwrap_or(after_marker.len());
197	            let candidate = &after_marker[..digit_end];
198	            // Guards against a non-numeric `code(...)` producing a bogus match.
199	            if candidate.len() > 1 && candidate[1..].chars().all(|c| c.is_ascii_digit()) {
200	                codes.push(candidate.to_string());
201	            }
202	            rest = &after_marker[digit_end..];
203	        }
204	        codes
205	    }
