207	    /// Asserts that every `#[diagnostic(code(...))]` value across every file in
208	    /// [`DIAGNOSTIC_CODE_SOURCE_FILES`] is unique workspace-wide. Duplicate diagnostic codes are
209	    /// a real user-facing bug (E-codes are meant to be a stable, searchable identifier for one
210	    /// specific error condition) — see this test's doc comment on `DIAGNOSTIC_CODE_SOURCE_FILES`
211	    /// for the collision this replaced a broken, silently-incomplete version of the check.
212	    #[test]
213	    fn test_all_diagnostic_codes_are_unique() {
214	        let mut seen: std::collections::BTreeMap<String, &str> = std::collections::BTreeMap::new();
215	        for (file, text) in DIAGNOSTIC_CODE_SOURCE_FILES {
216	            for code in extract_diagnostic_codes(text) {
217	                if let Some(first_file) = seen.insert(code.clone(), file) {
218	                    panic!("Duplicate diagnostic code {code}: declared in both {first_file} and {file}");
219	                }
220	            }
221	        }
222	        assert!(
223	            seen.len() > 50,
224	            "expected at least 50 distinct diagnostic codes across the workspace (81 at the \
225	             time this test was written), got {} -- extract_diagnostic_codes likely stopped \
226	             matching real source (check DIAGNOSTIC_CODE_SOURCE_FILES's include_str! paths \
227	             still resolve)",
228	            seen.len()
229	        );
230	    }
