233	    fn every_diagnostic_code_is_documented() {
234	        let doc = include_str!("../../../docs/errors.md");
235	        let missing: Vec<String> = DIAGNOSTIC_CODE_SOURCE_FILES
236	            .iter()
237	            .flat_map(|(_, text)| extract_diagnostic_codes(text))
238	            .filter(|code| !doc.contains(&format!("| {code} |")))
239	            .collect();
240	        assert!(missing.is_empty(), "codes missing from docs/errors.md: {missing:?}");
241	    }
