10	/// An exact, ecosystem-qualified package identity for durable release operations.
11	///
12	/// Unlike PackageId, this type has no bare form and therefore cannot use
13	/// wildcard matching across ecosystems.
14	#[derive(Clone, Debug, PartialEq, Eq, Hash, Deserialize)]
15	#[serde(try_from = "String")]
16	pub struct ReleasePackageId {
17	    ecosystem: Ecosystem,
18	    name: String,
19	}
20	
21	string_json_schema!(ReleasePackageId);
22	
23	impl ReleasePackageId {
24	    /// Creates an exact release package identity.
25	    ///
26	    /// # Errors
27	    ///
28	    /// Returns ReleasePackageIdParseError when name is not valid in the
29	    /// existing package-identity grammar.
30	    pub fn new(ecosystem: Ecosystem, name: impl AsRef<str>) -> Result<Self, ReleasePackageIdParseError> {
31	        let name = name.as_ref();
32	        if let Err(reason) = check_release_package_name(ecosystem, name) {
33	            return Err(ReleasePackageIdParseError::UnsafeName {
34	                raw: format!("{}/{}", ecosystem.prefix(), name),
35	                reason,
36	            });
37	        }
38	        let raw = format!("{}/{}", ecosystem.prefix(), name);
39	        match PackageId::parse(&raw) {
40	            Ok(PackageId::Prefixed {
41	                ecosystem: parsed_ecosystem,
42	                name: parsed_name,
43	            }) if parsed_ecosystem == ecosystem && parsed_name == name => Ok(Self {
44	                ecosystem,
45	                name: parsed_name,
46	            }),
47	            _ => Err(ReleasePackageIdParseError::Malformed { raw }),
48	        }
49	    }
50	
51	    /// Parses the canonical 'ecosystem/name' release identity form.
52	    ///
53	    /// PackageId also accepts 'ecosystem:name'; release identities reject it
54	    /// so every durable encoding has exactly one spelling.
55	    pub fn parse(s: &str) -> Result<Self, ReleasePackageIdParseError> {
56	        if s.contains(':') {
57	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
58	        }
59	        let (prefix, name) = s
60	            .split_once('/')
61	            .ok_or_else(|| ReleasePackageIdParseError::MissingEcosystem { raw: s.to_string() })?;
62	        let ecosystem = Ecosystem::from_prefix(prefix)
63	            .ok_or_else(|| ReleasePackageIdParseError::UnknownEcosystem { raw: s.to_string() })?;
64	        let id = Self::new(ecosystem, name)?;
65	        if id.to_string() != s {
66	            return Err(ReleasePackageIdParseError::NonCanonical { raw: s.to_string() });
67	        }
68	        Ok(id)
69	    }
