126	#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
127	#[non_exhaustive]
128	pub enum ReleasePackageIdParseError {
129	    #[error("release package identity {raw} must include an ecosystem prefix")]
130	    MissingEcosystem { raw: String },
131	    #[error("release package identity {raw} has an unknown ecosystem prefix")]
132	    UnknownEcosystem { raw: String },
133	    #[error("release package identity {raw} is malformed")]
134	    Malformed { raw: String },
135	    #[error("release package identity {raw} is not in canonical ecosystem/name form")]
