141	/// The charset every release package name must satisfy, per ecosystem.
142	///
143	/// A release package name is not just a label: it becomes an argv word
144	/// (`npm view <name>@<version>`, `pnpm publish --filter=<name>`) and a URL
145	/// path segment (the cargo sparse index, the PyPI JSON API). `TagName` and
146	/// `GitHubRepository` already rule out the same hazards for their own
147	/// identities; this is the equivalent rule for package names, applied where
148	/// [`ReleasePackageId`] is minted so no release path can skip it.
149	///
150	/// Each ecosystem's real grammar is enforced rather than a lowest common
151	/// denominator, because a name outside it cannot name a publishable package
152	/// anyway and a plan-time rejection is cheaper than a half-published release.
153	fn check_release_package_name(ecosystem: Ecosystem, name: &str) -> Result<(), &'static str> {
154	    if name.is_empty() {
155	        return Err("name is empty");
156	    }
157	    if name.len() > 214 {
158	        return Err("name is longer than any registry accepts");
159	    }
160	    if name.starts_with('-') {
161	        return Err("a leading `-` would be read as a command-line option");
162	    }
163	    if name.chars().any(|c| c.is_control() || c.is_whitespace()) {
164	        return Err("name contains a control character or whitespace");
165	    }
166	    // `/` is allowed only as the single separator of an npm `@scope/name`,
167	    // handled below; every other character here can change the meaning of a
168	    // URL path or an argv word.
169	    if name.contains(['?', '#', '%', '\\', ':', '@']) && !(ecosystem == Ecosystem::Npm && name.starts_with('@')) {
170	        return Err("name contains a character that can alter a URL path or argv word");
171	    }
172	    match ecosystem {
173	        Ecosystem::Cargo => check_cargo_name(name),
174	        Ecosystem::Npm => check_npm_name(name),
175	        Ecosystem::Pypi => check_pypi_name(name),
176	        // No publish path is implemented for these, so only the shared
177	        // argv/URL rules above apply; a `/` would still traverse a URL path.
178	        _ => {
179	            if name.contains('/') {
180	                Err("name contains a path separator")
181	            } else {
182	                Ok(())
183	            }
184	        }
185	    }
186	}
187	
188	/// crates.io: ASCII alphanumerics, `-` and `_`, starting with a letter or `_`.
189	fn check_cargo_name(name: &str) -> Result<(), &'static str> {
190	    let first = name.chars().next().unwrap_or('\0');
191	    if !(first.is_ascii_alphabetic() || first == '_') {
192	        return Err("a cargo crate name must start with a letter or underscore");
193	    }
194	    if !name
195	        .bytes()
196	        .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_'))
197	    {
198	        return Err("a cargo crate name may only contain letters, digits, `-` and `_`");
199	    }
200	    Ok(())
201	}
202	
203	/// npm: lowercase, URL-safe, with an optional single `@scope/` prefix.
204	fn check_npm_name(name: &str) -> Result<(), &'static str> {
205	    let (scoped, unscoped) = match name.strip_prefix('@') {
206	        Some(rest) => {
207	            let (scope, package) = rest
208	                .split_once('/')
209	                .ok_or("an npm scope must be followed by `/` and a package name")?;
210	            check_npm_segment(scope, true)?;
211	            (true, package)
212	        }
213	        None => (false, name),
214	    };
215	    check_npm_segment(unscoped, scoped)
216	}
217	
218	/// npm allows legacy uppercase names and, only under a scope, a leading `.` or `_`.
219	fn check_npm_segment(segment: &str, scoped: bool) -> Result<(), &'static str> {
220	    let first = segment.chars().next().unwrap_or('\0');
221	    let leading_ok = first.is_ascii_alphanumeric() || (scoped && matches!(first, '.' | '_'));
222	    if !leading_ok {
223	        return Err(
224	            "an npm name segment must start with a letter or digit (a scoped name may also start with `.` or `_`)",
225	        );
226	    }
227	    if !segment
228	        .bytes()
229	        .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.'))
230	    {
231	        return Err("an npm name segment may only contain letters, digits, `-`, `_` and `.`");
232	    }
233	    Ok(())
234	}
235	
236	/// PEP 508: alphanumerics separated by single `-`, `_` or `.` runs, starting
237	/// and ending with an alphanumeric.
238	fn check_pypi_name(name: &str) -> Result<(), &'static str> {
239	    let boundary_ok = |c: Option<char>| c.is_some_and(|c| c.is_ascii_alphanumeric());
240	    if !boundary_ok(name.chars().next()) || !boundary_ok(name.chars().last()) {
241	        return Err("a PyPI project name must start and end with a letter or digit");
242	    }
243	    if !name
244	        .bytes()
245	        .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.'))
246	    {
247	        return Err("a PyPI project name may only contain letters, digits, `-`, `_` and `.`");
248	    }
249	    Ok(())
250	}
