220	/// then collapse any run of hyphens, dots, or underscores into a single
221	/// underscore. This makes name-equality comparisons and wheel-filename
222	/// construction agree that "my-package", "my_package", "my.package", and
223	/// "My--Package" all refer to the same PyPI distribution -- PEP 503's own
224	/// canonicalization rule (`re.sub(r"[-_.]+", "-", name).lower()`), joined
225	/// with `_` to match PEP 427's wheel-filename escaping instead of PEP
226	/// 503's own `-` (the join character doesn't affect equality comparisons,
227	/// only which convention a caller building a filename needs).
228	pub fn normalize_pypi_package_name(name: &str) -> String {
229	    pypi_name_parts(name).join("_")
230	}
