238	/// The name and version of a wheel or sdist filename; an sdist's last `-` splits them, as a version has no hyphen.
239	pub fn pypi_dist_filename_parts(filename: &str) -> Option<(&str, &str)> {
240	    if let Some(stem) = filename.strip_suffix(".whl") {
241	        let mut segments = stem.split('-');
242	        return Some((segments.next()?, segments.next()?));
243	    }
244	    [".tar.gz", ".tar.bz2", ".tar.xz", ".tar.Z", ".zip"]
245	        .into_iter()
246	        .find_map(|ext| filename.strip_suffix(ext))
247	        .and_then(|stem| stem.rsplit_once('-'))
248	}
