258	/// Whether `filename` is a wheel or sdist of `package_name` at exactly `version`.
259	pub fn pypi_dist_belongs_to(filename: &str, package_name: &str, version: &Version) -> bool {
260	    pypi_dist_filename_parts(filename).is_some_and(|(name, candidate)| {
261	        normalize_pypi_project_name(name) == normalize_pypi_project_name(package_name)
262	            && Version::parse(candidate, version.grammar())
263	                .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
264	    })
